$ErrorActionPreference='Stop'
$root='F:\CABAL_291_TEST'
function Need($ok,[string]$why){if(!$ok){throw $why}}
function Sha([byte[]]$body){$h=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($h.ComputeHash($body))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}}
function AtomicWrite([string]$path,[byte[]]$body){$tmp=$path+'.new-'+[guid]::NewGuid().ToString('N');try{[IO.File]::WriteAllBytes($tmp,$body);Move-Item -LiteralPath $tmp -Destination $path -Force}finally{if(Test-Path -LiteralPath $tmp){Remove-Item -LiteralPath $tmp -Force}}}
Need ($env:OS -eq 'Windows_NT' -and [Environment]::Is64BitProcess) 'WINDOWS_X64_POWERSHELL_REQUIRED'
Need (Test-Path -LiteralPath "$root\Bin\x64\CabalMain.exe" -PathType Leaf) 'TEST_CLIENT_NOT_FOUND'
Need ((Get-FileHash -LiteralPath "$root\Bin\x64\CabalMain.exe" -Algorithm SHA256).Hash -eq '52e7956d4781fea1f0369cac8ab1eac4c3ddec2d1977c6557be53ec2b79885d9') 'CLIENT291_BUILD_DIFFERS'
Need (!(Get-Process -Name CabalMain -ErrorAction SilentlyContinue)) 'AIZVER_SPELI_PIRMS_UZSTADISANAS'
$own=Join-Path $root '.ep36-runtime'
if(Test-Path -LiteralPath $own){Need (!((Get-Item -LiteralPath $own).Attributes -band [IO.FileAttributes]::ReparsePoint)) 'RUNTIME_FOLDER_REPARSE_REFUSED'}
[void][IO.Directory]::CreateDirectory($own)
$profileName='profile-052d41e8653c-'+[guid]::NewGuid().ToString('N').Substring(0,8)
$profile=Join-Path $own $profileName
[void][IO.Directory]::CreateDirectory($profile)
$zip=[Convert]::FromBase64String('')
Need ((Sha $zip) -eq '052d41e8653c93f8f6a28a2f54108158986e408ff24df5b06c50d3a9fe57c409') 'CLIENT_PAYLOAD_HASH_DIFFERS'
# Windows PowerShell 5.1 does not automatically load the separate assembly
# containing ZipArchive when its FileSystem companion is loaded.
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem
$memory=[IO.MemoryStream]::new($zip)
$archive=[IO.Compression.ZipArchive]::new($memory,[IO.Compression.ZipArchiveMode]::Read)
try{
 foreach($entry in $archive.Entries){
  Need ($entry.FullName -match '^[A-Za-z0-9_.-]+$' -and $entry.Length -lt 1048576) 'CLIENT_PAYLOAD_MEMBER_INVALID'
  $stream=$entry.Open();$buffer=[IO.MemoryStream]::new()
  try{$stream.CopyTo($buffer);[IO.File]::WriteAllBytes((Join-Path $profile $entry.FullName),$buffer.ToArray())}finally{$stream.Dispose();$buffer.Dispose()}
 }
}finally{$archive.Dispose();$memory.Dispose()}
$hashes=Get-Content -LiteralPath (Join-Path $profile 'hashes.json') -Raw | ConvertFrom-Json
foreach($property in $hashes.PSObject.Properties){Need ((Get-FileHash -LiteralPath (Join-Path $profile $property.Name) -Algorithm SHA256).Hash -eq $property.Value) ('CLIENT_MEMBER_HASH_DIFFERS_'+$property.Name)}
$compiler=Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe'
Need (Test-Path -LiteralPath $compiler -PathType Leaf) 'WINDOWS_FRAMEWORK_COMPILER_MISSING'
$automation=[System.Management.Automation.PowerShell].Assembly.Location
$launcher=Join-Path $profile 'Launcher.exe'
'Sagatavoju palaideju speles mape...'
& $compiler /nologo /target:exe /platform:x64 /optimize+ ("/reference:"+$automation) ("/out:"+$launcher) (Join-Path $profile 'LauncherHost.cs')
Need ($LASTEXITCODE -eq 0 -and (Test-Path -LiteralPath $launcher)) 'OWN_LAUNCHER_BUILD_FAILED; SERVER_NOT_CHANGED'
$active=[ordered]@{Profile=$profileName;Files=$hashes;LauncherSHA=(Get-FileHash -LiteralPath $launcher -Algorithm SHA256).Hash;CostumeRuntime='r6-crest-291';InstalledUTC=[DateTime]::UtcNow.ToString('o')}
$runner=@'
$ErrorActionPreference='Stop'
$root='F:\CABAL_291_TEST'
$own=Join-Path $root '.ep36-runtime'
$active=Get-Content -LiteralPath (Join-Path $own 'active.json') -Raw | ConvertFrom-Json
if($active.Profile -notmatch '^profile-[a-f0-9-]+$'){throw 'RUNTIME_PROFILE_PATH_INVALID'}
$profile=Join-Path $own $active.Profile
foreach($p in $active.Files.PSObject.Properties){if((Get-FileHash -LiteralPath (Join-Path $profile $p.Name) -Algorithm SHA256).Hash -ne $p.Value){throw ('RUNTIME_FILE_CHANGED_'+$p.Name)}}
$launcher=Join-Path $profile 'Launcher.exe'
if((Get-FileHash -LiteralPath $launcher -Algorithm SHA256).Hash -ne $active.LauncherSHA){throw 'OWN_LAUNCHER_CHANGED'}
if(Get-Process -Name CabalMain -ErrorAction SilentlyContinue){throw 'CABAL_jau_ir_palaists'}
Start-Process -FilePath $launcher -WorkingDirectory $profile -Verb RunAs
'@
$start="@echo off`r`ncd /d `"%~dp0`"`r`npowershell.exe -NoLogo -NoProfile -ExecutionPolicy Bypass -File `"%~dp0.ep36-runtime\Start-Game.ps1`"`r`nif errorlevel 1 pause`r`n"
$backup=Join-Path ([Environment]::GetFolderPath('MyDocuments')) ('CABAL291-Launcher-Backups\'+[guid]::NewGuid().ToString('N'))
[void][IO.Directory]::CreateDirectory($backup)
foreach($path in @((Join-Path $root 'Start.bat'),(Join-Path $own 'Start-Game.ps1'),(Join-Path $own 'active.json'))){
 if(Test-Path -LiteralPath $path){Need (!((Get-Item -LiteralPath $path).Attributes -band ([IO.FileAttributes]::ReparsePoint -bor [IO.FileAttributes]::ReadOnly))) 'LAUNCHER_ENTRY_NOT_WRITABLE';Copy-Item -LiteralPath $path -Destination (Join-Path $backup ([IO.Path]::GetFileName($path)))}
}
AtomicWrite (Join-Path $own 'active.json') ([Text.Encoding]::UTF8.GetBytes(($active|ConvertTo-Json -Depth 5)))
AtomicWrite (Join-Path $own 'Start-Game.ps1') ([Text.Encoding]::ASCII.GetBytes($runner))
AtomicWrite (Join-Path $root 'Start.bat') ([Text.Encoding]::ASCII.GetBytes($start))
'PASTAVIGA_PALAISANA='+$root+'\Start.bat'
'PALAIDEJA_REZERVES_KOPIJA='+$backup
$server=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
Need ((Sha ([Text.Encoding]::UTF8.GetBytes($server))) -eq '504c2ba5c3041d2dfb0299fce3853891f5b4eadc1ab256301aa1a1f8665c7919') 'SERVER_INSTALLER_PAYLOAD_DIFFERS'
'Costume servera parbaude un uzstadisana; tikai testa VM 192.168.56.101...'
$server | ssh root@192.168.56.101 python3 - --apply
Need ($LASTEXITCODE -eq 0) 'COSTUME_SERVER_INSTALL_NOT_CONFIRMED; START_BAT_READY; ATSUTI_IZVADI'
'COSTUME291_UZSTADITS; PALAID_F_CABAL_291_TEST_START_BAT'
